//! Regex operation rows (RX-10e): the real compiler artifacts for the
//! `corpus/regex` cells the Wasm backend lowers end to end run through the
//! product host and match their checked-in `.expected` oracles (the oracle is
//! the MIR runner's output, so the Wasm host agrees with the reference
//! semantics). The artifacts are regenerated by `radix emit -t wasm-text
//! radix/corpus/regex/<cell>.fab`; each `.expected` is the sibling oracle.
//! The closure form (`replace_each`) has no lowered cell on Wasm yet (its
//! format arity is a separate backend limit), so it is proved by a synthetic
//! module against the host row.

use faber_host_wasm::{RunConfig, RunOutcome, WasmRtV1Host};

fn run_wat(wat: &str) -> RunOutcome {
    let bytes = wat::parse_str(wat).expect("module must parse");
    WasmRtV1Host::new()
        .expect("host init")
        .run(&bytes, &RunConfig::default())
}

fn assert_cell(name: &str, wat: &str, expected: &str) {
    assert_eq!(
        run_wat(wat),
        RunOutcome::Success {
            stdout: expected.to_owned(),
            stderr: String::new(),
        },
        "regex/{name}.fab must run through the product host matching its .expected oracle"
    );
}

#[test]
fn find_cell_matches_expected() {
    assert_cell(
        "find",
        include_str!("fixtures/regex-find.wat"),
        include_str!("fixtures/regex-find.expected"),
    );
}

#[test]
fn find_all_cell_matches_expected() {
    assert_cell(
        "find-all",
        include_str!("fixtures/regex-find-all.wat"),
        include_str!("fixtures/regex-find-all.expected"),
    );
}

